   481   * Get the direction from the origin to a given neighbor. This is effectively
   482   * the reverse operation for h3NeighborRotations. Returns INVALID_DIGIT if the
   483   * cells are not neighbors.
   484   *
   485   * TODO: This is currently a brute-force algorithm, but as it's O(6) that's
   486   * probably acceptable.
   487   */
   488  Direction directionForNeighbor(H3Index origin, H3Index destination) {
   489      bool isPent = H3_EXPORT(isPentagon)(origin);
   490      // Checks each neighbor, in order, to determine which direction the
   491      // destination neighbor is located. Skips CENTER_DIGIT since that
   492      // would be the origin; skips deleted K direction for pentagons.
   493      for (Direction direction = isPent ? J_AXES_DIGIT : K_AXES_DIGIT;
   494           direction < NUM_DIGITS; direction++) {
   495          H3Index neighbor;
   496          int rotations = 0;
   497          H3Error neighborError =
   498              h3NeighborRotations(origin, direction, &rotations, &neighbor);
   499          if (!neighborError && neighbor == destination) {
   500              return direction;
   501          }
   502      }
   503      return INVALID_DIGIT;
   504  }
